    Done(HttpResponse),
    /// Busy: requeue and send again, unchanged, no earlier than this instant.
    ResendAt(Instant),
}

#[derive(Clone)]
pub struct HttpClient { transport: Arc<dyn Transport>, policy: ResendPolicy, log: GeneralLogger }
impl HttpClient {
